function getGradienteCor(color1, color2, weight){
    if (color1==color2){
        div = 1
    }else{
        div = (color2[0]-color1[0])
    }

    weight = ((weight-color1[0])*100)/div;
    weight -= 100
    weight *=-1
    color1 = color1[1]
    color2 = color2[1]
    p = weight

    w = p * 2 - 1
    w1 = (w/1+1) / 2/100
    w2 = 1 - w1
    rgb = [Math.round(color1[0] * w1 + color2[0] * w2),
        Math.round(color1[1] * w1 + color2[1] * w2),
        Math.round(color1[2] * w1 + color2[2] * w2)]
    return rgb;
}





function createGround(width, height){
    var inc = 0.2;
    var yoff = 0;
    var result = [];
    for (var i = 0 ; i < width; i++) {
        result[i] = [];
        var xoff = 0;
        for (var j = 0; j < height; j++) {
            result[i][j] =  0;
            var y = noise(xoff,yoff)*100;
            // y = 1000;
            if(i==0 || i==width-1 || j==0 || j==height-1){
                var t = new Tile(0);
                result[i][j] =  t;
            }else{
                if(y>40){
                    var t = new Tile(1);
                    result[i][j] =  t;
                }else{
                    var t = new Tile(0);
                    result[i][j] =  t;
                }
            }
            xoff += inc;
        }
        yoff += inc;
    }
    return result;
}



